"""Cancellation scenarios: 1 case, one test each."""

from pathlib import Path

import pytest

from api_test_framework import Expect, load_rows, unique_id

PROJECT = Path(__file__).resolve().parents[2]
TC040_ROWS = load_rows(PROJECT / "data/cancellation-scenarios-tc040.csv")


@pytest.mark.functional
@pytest.mark.cancellation
@pytest.mark.writes
@pytest.mark.case("TC040")
@pytest.mark.priority("P0")
@pytest.mark.parametrize("row", TC040_ROWS, ids=lambda row: str(row["case"]) if "case" in row else None)
def test_tc040_the_refund_depends_on_when_the_booking_is_cancelled(api, context, row):
    """The refund depends on when the booking is cancelled. Criteria: AC-2, AC-3."""
    unique = unique_id()
    # 1. POST /bookings
    response = api.post("/bookings", json={
        "passenger_name": f"Asha Rao {unique}",
        "email": f"asha.{unique}@testdata.example",
        "amount": 250,
        "booked_at": row["booked_at"],
    })
    Expect(response).status_is(201)
    context.remember("pnr", response.value("pnr"))
    # 2. POST /bookings/{{pnr}}/cancel
    response = api.post(f"/bookings/{context.get('pnr')}/cancel", json={"cancelled_at": row["cancelled_at"]})
    (Expect(response).status_is(200)
        .field_equals("refund_allowed", row["refund_allowed"])
        .field_equals("refund_amount", row["refund_amount"]))
